"""Generate committee and interview PDFs from computed results."""
import json
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.enums import TA_LEFT
R=Path(__file__).resolve().parents[1]
d=json.loads((R/'public/analysis.json').read_text())
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='Kicker',fontName='Helvetica-Bold',fontSize=9,textColor=colors.HexColor('#536474'),spaceAfter=14))
styles['Title'].fontName='Times-Roman';styles['Title'].fontSize=29;styles['Title'].leading=33;styles['Title'].alignment=TA_LEFT;styles['Title'].textColor=colors.HexColor('#122b3b')
styles['Heading2'].textColor=colors.HexColor('#215a79');styles['Heading2'].spaceBefore=16
styles['BodyText'].fontSize=10;styles['BodyText'].leading=15;styles['BodyText'].spaceAfter=9

def p(t,style='BodyText'):return Paragraph(t,styles[style])
def table(rows,widths=None):
    t=Table([[p(escape(str(c))) for c in row]for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf2f6')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,-1),.4,colors.HexColor('#dce3ea')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return t

def footer(canvas,doc):
    canvas.setFont('Helvetica',8);canvas.setFillColor(colors.HexColor('#536474'));canvas.drawString(42,27,'Credit Analyst Lab | Independent illustrative case | 30 September 2026');canvas.drawRightString(553,27,str(doc.page))
def save(name,story,title):
    SimpleDocTemplate(str(R/'public'/name),pagesize=(595,842),rightMargin=42,leftMargin=42,topMargin=42,bottomMargin=45,title=title,author='Nabilvisi / Credit Analyst Lab').build(story,onFirstPage=footer,onLaterPages=footer)
f=lambda x:f'{x:.2f}'
b=d['scenarios']['base'];down=d['scenarios']['downside'];rb=d['resized']['base'];rd=d['resized']['downside'];rs=d['resized']['severe']
story=[p('CREDIT COMMITTEE / EQUIPMENT FINANCE','Kicker'),p('Restructure the request.<br/>Verify the first exit.','Title'),p('PT Nusantara Earthworks - fictional Indonesian mining-services contractor. Independent interview case prepared for the Komatsu Astra Finance Credit Analyst role. No actual borrower, lender approval, affiliation or prior credit experience is claimed.'),p('Recommendation','Heading2'),p(f'Defer approval of the requested Rp21bn. Evaluate a Rp16bn facility cap, 48-month monthly amortization and 13% annual nominal base rate, subject to diligence. Require Rp14bn fresh customer equity toward Rp30bn of assets, separately funded liquidity and a three-payment reserve. Base DSCR improves from {f(b["dscr"])}x to {f(rb["dscr"])}x. Downside improves from {f(down["dscr"])}x to {f(rd["dscr"])}x.'),p(f'This is not an approval. After the modeled collection delay, the resized first-year downside DSCR is only {f(rd["firstYearDscr"])}x; severe steady-state coverage is {f(rs["dscr"])}x. Unverified contracts, equity, legal security or customer payment capacity require deferral or decline.'),table([['Term','Requested','Proposed for diligence'],['Asset package','5 units x Rp6bn','Rp30bn total'],['Facility / equity','Rp21bn / Rp9bn','Rp16bn / Rp14bn'],['Tenor / repayment','48 months / equal monthly','Same; no balloon'],['Monthly base payment',f'Rp{f(b["debtService"])}bn',f'Rp{f(rb["debtService"])}bn'],['Three-payment base reserve',f'Rp{f(b["reserve"])}bn',f'Rp{f(rb["reserve"])}bn']],[155,175,181]),p('Risk view','Heading2'),p('Primary exit: contracted project collections. Secondary exit: recoverable equipment value. Project cash is assumed segregated and there is no existing project debt. Group-wide obligations, distributions and cross-default exposure are not known and must be underwritten before approval.'),PageBreak(),p('Cash flow and downside','Title'),p('Synthetic project assumptions','Heading2'),p('Five units; 250 available hours per unit per month; 75% utilization; Rp1.85m hourly tariff. Fuel Rp0.36m and other variable costs Rp0.26m per billed hour. Fixed costs Rp0.12bn/month; depreciation Rp0.25bn/month; maintenance capex reserve Rp0.075bn/month. All are assumptions, not dealer quotes or KAF terms.'),table([['Monthly cash bridge','Rp billion'],['Revenue',f(b['revenue'])],['Fuel / other variable costs',f(b['fuel']+b['other'])],['Fixed costs','0.12'],['EBITDA',f(b['ebitda'])],['Cash-tax proxy',f(b['tax'])],['Maintenance capex reserve','0.075'],['CFADS',f(b['cfads'])],['Requested debt service',f(b['debtService'])]],[330,181]),p('Tax proxy: max(0, EBITDA - depreciation) x 22%. Interest is not deducted in this conservative cash-tax proxy. This is not a legal tax calculation. Maintenance expense and capex must be validated to avoid omission or double counting.'),p('Operating and liquidity tests','Heading2'),table([['Facility / scenario','Monthly DSCR','Year 1 incl. DSO','DSO cash need'],*[ [f'{facility} / {key}',f'{v["dscr"]:.2f}x',f'{v["firstYearDscr"]:.2f}x',f'Rp{v["wcShock"]:.2f}bn']for facility,scenarios in [('Rp21bn',d['scenarios']),('Rp16bn',d['resized'])]for key,v in scenarios.items()]],[150,110,130,121]),p('Downside: utilization 65%, tariff -5%, fuel +15%, interest 16%, DSO 75 days. Severe: utilization 50%, tariff -10%, fuel +25%, interest 18%, DSO 105 days. Interest shocks apply only to repricing/refinancing exposure; a fixed-rate contract would hold its agreed rate.'),PageBreak(),p('Structure the protections','Title'),p('Liquidity and debt sizing','Heading2'),p(f'At Rp16bn, downside CFADS supports a steady-state DSCR of {f(rd["dscr"])}x. The algebraic downside capacity at a 1.10x stress floor is Rp{f(down["maxPrincipal"])}bn. The proposed Rp16bn cap is a judgmental buffer below that ceiling, not an optimized or approved policy limit.'),p(f'Require a separately funded Rp{f(rd["wcShock"])}bn collection buffer plus a three-payment reserve (Rp{f(rb["reserve"])}bn at base rate; Rp{f(rd["reserve"])}bn under repricing). Assumed unrestricted corporate cash is Rp6.50bn. After a downside reserve and collection shock, headroom is Rp{f(rd["liquidityHeadroom"])}bn; corporate liquidity cannot be relied upon until availability is confirmed. Customer equity must come from additional verified funds, not the same cash counted for reserves.'),p('Reverse stress','Heading2'),p(f'At base tariff, fuel and interest, the requested facility reaches the illustrative 1.25x covenant at {d["breakEven"]:.1f}% utilization. Confirm minimum contracted hours and uptime; an equipment appraisal cannot fix a weak first exit.'),p('Collateral and expected loss','Heading2'),table([['Rp16bn case','Base','Downside','Severe'],['Gross recovery (% of Rp30bn assets)','55%','45%','35%'],['Net proceeds after 10% cost',*[f'Rp{v["netRecovery"]:.2f}bn'for v in d['resized'].values()]],['Uncovered principal',*[f'Rp{v["loss"]:.2f}bn'for v in d['resized'].values()]],['Judgmental one-year PD','3%','7%','15%'],['Illustrative expected loss',*[f'Rp{v["expectedLoss"]:.2f}bn'for v in d['resized'].values()]]],[220,97,97,97]),p('Expected loss = assumed PD x LGD x origination EAD. This is a teaching example, not a calibrated score, IFRS 9 estimate or actual rating. Recovery excludes delay, tax and senior claims. Validate resale values independently, liens, title, insurance, serial numbers, asset location, maintenance and repossession/redeployment costs.'),p('Security and account controls','Heading2'),p('Obtain legally enforceable equipment security; full insurance with lender interest; controlled collection account and assignment of proceeds where feasible. Indonesian counsel must determine enforceability, perfection and appropriate lease/security documentation. Align contract duration, payment terms and facility tenor.'),PageBreak(),p('Diligence, monitoring and evidence','Title'),p('Five conditions before a decision','Heading2'),p('1. Reconcile audited financials, tax filings, bank transactions and all group debt. Normalize one-offs, related-party balances and EBITDA-to-cash conversion.<br/>2. Verify beneficial ownership, authorized SLIK/bureau results, payment history and adverse records.<br/>3. Validate project contract, minimum volumes, payment protections, permits, mine-client creditworthiness and remaining work of at least the loan tenor.<br/>4. Conduct a project visit: technical suitability, uptime, maintenance, fuel records, HSE, site access and redeployment.<br/>5. Verify additional equity, unencumbered liquidity, insurance, security perfection and account controls. Track missing documents with Marketing; do not infer absence of risk from absence of data.'),p('Monitoring plan - illustrative triggers','Heading2'),table([['Trigger','Action'],['DSCR below 1.25x','Watchlist; review cash flow and cure plan'],['DSO above 60 days','Payer confirmation; weekly collections'],['Utilization below 70% for two months','Project visit; contract and hours review'],['Any payment missed','Immediate escalation and arrears handling'],['Permit lapse or contract termination','Freeze additional exposure; legal/recovery review']],[250,261]),p('Public data and limitations','Heading2'),p('EIA Brent daily prices via github.com/datasets/oil-prices, annual arithmetic mean for 2015-2025. Brent is a fuel-risk proxy; not coal or Indonesian diesel. World Bank Indonesia GDP (NY.GDP.MKTP.CD) via github.com/datasets/gdp, nominal current USD, available through 2023 in this mirror. Neither series determines creditworthiness. Refresh industry evidence before any live credit decision.'),p('Retrieved 30 September 2026; market cutoff 31 December 2025. Source mirrors: PDDL. Upstream: EIA public data; World Bank CC BY 4.0. Raw data, blob IDs and SHA-256 checksums are retained in data/sources.json. Reproduce via npm run build.'),p('Source: https://github.com/Nabilvisi/Credit-Analyst-Lab<br/>Missing: actual accounts, corporate debt service, cash-flow reconciliation, coal benchmarks, local diesel invoices, credit history, legal opinions and appraisal. Constant monthly operations omit seasonality, ramp-up, downtime timing, VAT, fees, exact lease accounting and recovery delay.')]
save('credit-memo.pdf',story,'Credit committee memo - Equipment finance')
guide=[p('INTERVIEW / 1 OCTOBER 2026','Kicker'),p('Explain the decision.<br/>Defend the assumptions.','Title'),p('Five-minute walkthrough','Heading2'),p('0-1 min: Introduce the five-unit Rp30bn asset package and Rp21bn financing request.<br/>1-2 min: Walk from billed hours to EBITDA, cash tax, maintenance capex, CFADS and base DSCR 1.39x.<br/>2-3 min: Apply downside; coverage falls to 0.96x. Explain why a healthy base case is insufficient.<br/>3-4 min: Resize to Rp16bn; downside becomes 1.26x, yet first-year coverage after collection delay is only 1.00x. Distinguish solvency from liquidity.<br/>4-5 min: Close with conditional structure, missing evidence, project survey and monthly monitoring.'),p('Positioning','Heading2'),p('My background is in engineering and data analysis. I built this independent equipment-finance case to show how I translate operating assumptions into a credit decision. I am moving into credit analysis; this is a learning project, not a loan I approved.'),p('Bahasa Indonesia - rekomendasi','Heading2'),p('Saya tidak akan merekomendasikan pembiayaan Rp21 miliar hanya karena DSCR base case mencapai 1,39 kali. Pada skenario downside, DSCR turun menjadi 0,96 kali. Saya akan mengevaluasi plafon Rp16 miliar, dengan verifikasi kontrak, sumber modal, arus kas, dan perlindungan likuiditas.'),p('DSCR yang cukup belum menjamin likuiditas aman. Ketika pembayaran customer melambat, kebutuhan modal kerja naik. Pada plafon Rp16 miliar, DSCR downside tahun pertama hanya sekitar 1,00 kali setelah tambahan piutang. Dana cadangan dan sumber likuiditas perlu diuji secara terpisah.'),PageBreak(),p('Questions to be ready for','Title')]
qas=[('Why not approve when base DSCR exceeds 1.25x?','The borrower must survive plausible stress. Utilization and fuel assumptions erode cash flow; collection timing can consume liquidity even when annual operations are profitable.'),('Why Rp16bn instead of Rp18.38bn?','Rp18.38bn is the algebraic downside maximum at a 1.10x floor. Rp16bn provides an additional judgmental buffer and roughly meets 1.25x steady-state downside coverage. It remains subject to verification.'),('Why is EBITDA not repayment cash?','Taxes, maintenance capex and working capital consume cash. Interest and principal are debt service. I avoid counting EBITDA as free cash flow.'),('How would you evaluate existing corporate debt?','Obtain a full debt schedule, guarantees, leases and contingent obligations; calculate consolidated CFADS and aggregate debt service. Project-only DSCR here cannot establish corporate capacity.'),('Why use Brent for a mining contractor?','It illustrates fuel-cost cyclicality. I do not infer coal prices or diesel invoices from Brent. I would request actual fuel invoices and check pass-through in the project contract.'),('How reliable is the PD?','It is uncalibrated and illustrative. I would use the lender-approved rating framework, verified repayment data, validation and documented overrides.'),('What happens during a project visit?','Verify equipment suitability, actual hours and maintenance logs; meet site management; check contract scope, permits, safety, access and backup work. Cross-check statements against operating evidence.'),('How do you work with Marketing?','Maintain a clear document request list, deadlines and unresolved issues. Explain which evidence is required for the decision; remain collaborative while preserving independent credit judgment.'),('What would make you decline?','Unverifiable or unstable contracts, weak payer credit, unexplained cash-flow discrepancies, insufficient fresh equity, legal security problems or unacceptable stress capacity.'),('What is your biggest learning gap?','I am building practical financial-statement and credit-process experience. I bring engineering and quantitative discipline, and I would learn the lender policy, systems and field practice from the team.')]
for q,a in qas:guide.extend([p(q,'Heading2'),p(a)])
guide.extend([p('Before the interview','Heading2'),p('Practice the five-minute case twice. Open the live site and keep the PDF offline. Use the scenario lab to show the Rp21bn downside, then the Rp16bn downside. Be explicit about assumptions and missing data. Ask about KAF credit process, project surveys, escalation and portfolio monitoring.')]);save('interview-guide.pdf',guide,'Interview guide - Credit Analyst Lab')
print('Generated credit-memo.pdf and interview-guide.pdf')
